import{_ as t,c as o,o as i,al as a}from"./chunks/framework.CT7RwC5a.js";const u=JSON.parse('{"title":"Test MC_06 - Optical Flow","description":"","frontmatter":{},"headers":[],"relativePath":"en/test_cards/mc_06_optical_flow.md","filePath":"en/test_cards/mc_06_optical_flow.md"}'),l={name:"en/test_cards/mc_06_optical_flow.md"};function r(n,e,s,h,c,d){return i(),o("div",null,e[0]||(e[0]=[a('<h1 id="test-mc-06-optical-flow" tabindex="-1">Test MC_06 - Optical Flow <a class="header-anchor" href="#test-mc-06-optical-flow" aria-label="Permalink to &quot;Test MC_06 - Optical Flow&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Test that optical flow works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Disconnect all GPS / compasses and ensure vehicle is using optical flow for navigation (<a href="./../sensor/optical_flow.html">setup information here</a>)</p><p>Ensure there are no other sources of positioning besides optical flow:</p><ul><li><a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>0</code></li></ul><p>Ensure that the drone can go into Altitude / Position mode while still on the ground</p><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ <a href="./../flight_modes_mc/altitude.html">Altitude mode</a></p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ <a href="./../flight_modes_mc/position.html">Position mode</a></p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><p>❏ Varying height terrain</p><p>    ❏ Put boxes on the ground to create varying heights in terrain</p><p>    ❏ Take off in position mode and fly over the boxes such that the downward facing rangefinder varies in value</p><p>    ❏ Do a few passes with varying amounts of time over the boxes (1-30 seconds if possible)</p><p>    ❏ Drone should not raise in height when flying over boxes</p><h2 id="landing" tabindex="-1">Landing <a class="header-anchor" href="#landing" aria-label="Permalink to &quot;Landing&quot;">​</a></h2><p>❏ Land in either Position or Altitude mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="expected-results" tabindex="-1">Expected Results <a class="header-anchor" href="#expected-results" aria-label="Permalink to &quot;Expected Results&quot;">​</a></h2><ul><li>Take-off should be smooth as throttle is raised</li><li>Drone should hold altitude in Altitude mode without wandering (over surface with many features)</li><li>Drone should hold position within 1 meter in Position mode without pilot moving sticks</li><li>No oscillations should present in any of the above flight modes</li><li>Drone should not raise in height when flying over boxes</li><li>Upon landing, copter should not bounce on the ground</li></ul>',28)]))}const _=t(l,[["render",r]]);export{u as __pageData,_ as default};
